from collections import Counter


def _runs(values, bg):
    runs = []
    i = 0
    while i < len(values):
        if values[i] == bg:
            i += 1
            continue
        color = values[i]
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        if j - i >= 2:
            runs.append((i, j, color))
        i = j
    return runs


def _matching_runs(first, second):
    for a in first:
        for b in second:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                return a, b
    return None


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pair = _matching_runs(_runs(grid[0], bg), _runs(grid[-1], bg))
    orientation = "horizontal"
    if pair is None:
        pair = _matching_runs(
            _runs([grid[r][0] for r in range(h)], bg),
            _runs([grid[r][-1] for r in range(h)], bg),
        )
        orientation = "vertical"
    if pair is None:
        raise ValueError("No matching equal-colored runs on opposite borders")

    out = [row[:] for row in grid]
    first, second = pair
    if orientation == "vertical":
        left, right = first, second
        bars = {(r, 0) for r in range(left[0], left[1])}
        bars.update((r, w - 1) for r in range(right[0], right[1]))
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or (r, c) in bars:
                    continue
                if left[0] <= r < left[1]:
                    # Ray from left bar to its marker; marker is recolored.
                    for cc in range(1, c):
                        out[r][cc] = color
                    out[r][c] = 4
                    paired_r = right[0] + (r - left[0])
                    # The corresponding right-edge lane extends across the grid,
                    # stopping just before its border bar.
                    if 0 <= paired_r < h:
                        for cc in range(w - 1):
                            out[paired_r][cc] = color
                elif right[0] <= r < right[1]:
                    # Ray from right bar to its marker; marker is recolored.
                    for cc in range(c + 1, w - 1):
                        out[r][cc] = color
                    out[r][c] = 4
                    paired_r = left[0] + (r - right[0])
                    # The corresponding left-edge lane begins just inside it.
                    if 0 <= paired_r < h:
                        for cc in range(1, w):
                            out[paired_r][cc] = color
    else:
        top, bottom = first, second
        bars = {(0, c) for c in range(top[0], top[1])}
        bars.update((h - 1, c) for c in range(bottom[0], bottom[1]))
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or (r, c) in bars:
                    continue
                if top[0] <= c < top[1]:
                    for rr in range(1, r):
                        out[rr][c] = color
                    out[r][c] = 4
                    paired_c = bottom[0] + (c - top[0])
                    if 0 <= paired_c < w:
                        for rr in range(h - 1):
                            out[rr][paired_c] = color
                elif bottom[0] <= c < bottom[1]:
                    for rr in range(r + 1, h - 1):
                        out[rr][c] = color
                    out[r][c] = 4
                    paired_c = top[0] + (c - bottom[0])
                    if 0 <= paired_c < w:
                        for rr in range(1, h):
                            out[rr][paired_c] = color
    return out


